<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useRouter} from 'vue-router'
import {useQuasar} from 'quasar'
import {Bell,ShieldCheck,SlidersHorizontal,CalendarClock,Plus,Trash2,Smartphone,Check,Info,Users} from 'lucide-vue-next'
import {useMonitor} from '../stores/monitor'
import {api,allPages} from '../services/api'
import {registerPush,unregisterPush,disconnectDevice} from '../services/push'
import {tabletAlarm,isTablet} from '../services/tabletAlarm'
import {date} from '../services/format'
import type {Rule} from '../types'
const store=useMonitor(),router=useRouter(),$q=useQuasar()
const rules=ref<Rule[]>([]),selected=ref<number|null>(null),form=ref<Rule|null>(null),pushEnabled=ref(true),devices=ref<{id:number;label:string;enabled:boolean;last_seen:string}[]>([]),maintenance=ref<{id:number;server:number;server_name:string;starts_at:string;ends_at:string;reason:string}[]>([]),busy=ref(false),error=ref(''),pushStatus=ref(''),adding=ref(false)
const backgroundAllowed=ref(false)
const mw=ref({server:0,starts_at:'',ends_at:'',reason:''})
const members=ref<{id:number;user__username:string;role:string}[]>([]),memberName=ref(''),memberRole=ref('viewer')
const manageable=computed(()=>store.data?.servers.filter(s=>s.role==='admin')||[])
async function load(){error.value='';try{const [r,p,d,m]=await Promise.all([allPages<Rule>('/alert-rules'),api('/notification-preferences'),api('/devices'),allPages<any>('/maintenance-windows')]);rules.value=r;pushEnabled.value=p.push_enabled;devices.value=d;maintenance.value=m;if(isTablet)backgroundAllowed.value=(await tabletAlarm.batteryStatus()).unrestricted;if(!selected.value)selected.value=manageable.value[0]?.id||null;chooseRule()}catch(e){error.value=(e as Error).message}}
function chooseRule(){form.value=JSON.parse(JSON.stringify(rules.value.find(r=>r.server===selected.value)||null));void loadMembers()}
async function loadMembers(){members.value=[];if(selected.value)try{members.value=await api(`/servers/${selected.value}/memberships`)}catch(e){error.value=(e as Error).message}}
async function saveRule(){if(!form.value)return;busy.value=true;try{await api(`/alert-rules/${form.value.id}`,{method:'PATCH',body:JSON.stringify(form.value)});await load();$q.notify({message:'Alert rules updated',color:'positive'})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function savePreference(value:boolean){try{await api('/notification-preferences',{method:'PATCH',body:JSON.stringify({push_enabled:value})});if(value)await push();else await unregisterPush();await load()}catch(e){pushEnabled.value=!value;error.value=(e as Error).message}}
async function push(){try{pushStatus.value=await registerPush(id=>router.push(`/alerts?incident=${id}`));await load()}catch(e){pushStatus.value=(e as Error).message}}
async function testAlarm(){try{await tabletAlarm.enable();await tabletAlarm.test();pushStatus.value='Tablet alarm started. Use Stop alarm to silence it.'}catch(e){pushStatus.value=(e as Error).message}}
async function silenceAlarm(){try{await tabletAlarm.silence();pushStatus.value='Alarm silenced. Monitoring continues.'}catch(e){pushStatus.value=(e as Error).message}}
async function alarmSettings(){try{await tabletAlarm.settings()}catch(e){pushStatus.value=(e as Error).message}}
async function allowBackgroundAlarms(){try{await tabletAlarm.allowBackgroundAlarms();pushStatus.value='Allow unrestricted battery use in Android, then return to Cronos.'}catch(e){pushStatus.value=(e as Error).message}}
const refreshBatteryStatus=()=>{if(isTablet&&document.visibilityState==='visible')void tabletAlarm.batteryStatus().then(r=>backgroundAllowed.value=r.unrestricted)}
async function testPush(){try{const r=await api('/notifications/test',{method:'POST',body:'{}'});pushStatus.value=r.message}catch(e){pushStatus.value=(e as Error).message}}
async function revoke(id:number){try{disconnectDevice(id);await api(`/devices/${id}`,{method:'DELETE'});await load()}catch(e){error.value=(e as Error).message}}
async function saveMaintenance(){busy.value=true;error.value='';try{await api('/maintenance-windows',{method:'POST',body:JSON.stringify({...mw.value,starts_at:new Date(mw.value.starts_at).toISOString(),ends_at:new Date(mw.value.ends_at).toISOString()})});adding.value=false;await load();await store.refresh();$q.notify({message:'Maintenance scheduled',color:'positive'})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function removeMaintenance(id:number){try{await api(`/maintenance-windows/${id}`,{method:'DELETE'});await load();await store.refresh()}catch(e){error.value=(e as Error).message}}
async function revokeMember(id:number){if(!selected.value)return;try{await api(`/servers/${selected.value}/memberships/${id}`,{method:'DELETE'});await loadMembers()}catch(e){error.value=(e as Error).message}}
async function saveMember(){if(!selected.value)return;try{await api(`/servers/${selected.value}/memberships`,{method:'POST',body:JSON.stringify({username:memberName.value,role:memberRole.value})});memberName.value='';await loadMembers()}catch(e){error.value=(e as Error).message}}
const pushEvent=(e:Event)=>{pushStatus.value=(e as CustomEvent).detail;void load()}
onMounted(()=>{void load();window.addEventListener('cronos:push-status',pushEvent);document.addEventListener('visibilitychange',refreshBatteryStatus)})
onUnmounted(()=>{window.removeEventListener('cronos:push-status',pushEvent);document.removeEventListener('visibilitychange',refreshBatteryStatus)})
</script>
<template><div class="page-header"><div><h1>Settings</h1><p class="subtitle">Monitoring that works the way you do.</p></div></div><div v-if="error" class="error-box" role="alert">{{error}}</div><div class="settings-grid"><section class="panel settings-panel"><header class="panel-header"><h2><Bell :size="19"/>Notifications</h2></header><div class="settings-body"><div class="setting-toggle"><div><b>Live notifications</b><p>{{isTablet?'Sound an alarm for incidents, even in the background or with the screen locked.':'Receive incident and recovery alerts while this app is open and connected.'}}</p></div><q-toggle v-model="pushEnabled" @update:model-value="savePreference" aria-label="Enable live notifications"/></div><div class="notice" :class="store.data?.monitoring.push_configured?'':'warning'">{{store.data?.monitoring.push_configured?'Live alerts are available. A network connection is required.':'Live notifications are not configured. Incident history remains available.'}}</div><div class="button-row"><q-btn outline no-caps @click="push"><Smartphone :size="16"/>Register this device</q-btn><q-btn flat no-caps @click="testPush">Send test notification</q-btn></div><template v-if="isTablet"><div class="notice" :class="backgroundAllowed?'':'warning'">{{backgroundAllowed?'Background alarms are allowed while the screen is off.':'Android may pause alarms when the tablet is idle. Allow background alarms for this device.'}}<q-btn v-if="!backgroundAllowed" flat no-caps label="Allow background alarms" @click="allowBackgroundAlarms"/></div><div class="button-row"><q-btn outline no-caps label="Test tablet alarm" @click="testAlarm"/><q-btn flat no-caps label="Stop alarm" @click="silenceAlarm"/><q-btn flat no-caps label="Alarm sound settings" @click="alarmSettings"/></div><p class="muted">Allow Android notifications and keep alarm volume audible. Background monitoring shows an ongoing notification. Allow background alarms so Android does not pause the connection while idle. Continuous monitoring uses additional battery. Each alarm rings for up to 30 seconds; silencing it does not acknowledge the incident. Force-stopping Cronos or restarting the tablet requires opening it again.</p></template><p v-if="pushStatus" class="notice" role="status">{{pushStatus}}</p><h3>Registered devices</h3><div v-for="d in devices.filter(d=>d.enabled)" :key="d.id" class="detail-line"><span>{{d.label}}<small class="muted block">Last seen {{date(d.last_seen)}}</small></span><q-btn flat round size="sm" aria-label="Revoke device" @click="revoke(d.id)"><Trash2 :size="17"/></q-btn></div><p v-if="!devices.some(d=>d.enabled)" class="muted">No registered devices.</p></div></section>
<section class="panel settings-panel"><header class="panel-header"><h2><SlidersHorizontal :size="19"/>Alert rules</h2></header><form v-if="manageable.length" @submit.prevent="saveRule" class="settings-body form-fields"><q-select v-model="selected" outlined emit-value map-options :options="manageable.map(s=>({label:s.name,value:s.id}))" label="Server" @update:model-value="chooseRule"/><template v-if="form"><div class="form-two"><q-input v-model.number="form.health_threshold" outlined label="Alert below (%)" type="number" min="0" max="99"/><q-input v-model.number="form.recovery_threshold" outlined label="Recover at (%)" type="number" min="1" max="100"/></div><div class="form-two"><q-input v-model.number="form.persistence" outlined label="Consecutive samples" type="number" min="1" max="10"/><q-input v-model.number="form.stale_seconds" outlined label="Agent stale after (s)" type="number" min="60" max="3600"/></div><q-input v-model.number="form.reminder_minutes" outlined label="Reminder interval (minutes)" type="number" min="1" max="1440"/><p class="muted caption">At the default settings, exactly 50% does not alert. Recovery requires 60% for three samples. Acknowledgement stops reminders.</p><q-btn type="submit" unelevated no-caps color="primary" label="Save rules" :loading="busy"/></template></form><p v-else class="settings-body muted">Only server administrators can configure rules.</p></section>
<section class="panel settings-panel"><header class="panel-header"><h2><CalendarClock :size="19"/>Maintenance windows</h2><q-btn v-if="manageable.length" flat dense no-caps @click="mw.server=manageable[0]!.id;adding=true"><Plus :size="17"/>Schedule</q-btn></header><div class="settings-body"><p class="muted">Collection continues during maintenance. Live alerts and reminders pause until the window ends.</p><div v-for="m in maintenance" :key="m.id" class="maintenance-row"><div><b>{{m.server_name}} · {{m.reason}}</b><small>{{date(m.starts_at)}} → {{date(m.ends_at)}}</small></div><q-btn v-if="manageable.some(s=>s.id===m.server)" flat round size="sm" aria-label="Remove maintenance window" @click="removeMaintenance(m.id)"><Trash2 :size="17"/></q-btn></div><p v-if="!maintenance.length" class="muted">No maintenance scheduled.</p></div></section>
<section class="panel settings-panel"><header class="panel-header"><h2><Users :size="19"/>Server access</h2></header><div class="settings-body"><q-btn v-if="store.user?.is_admin" flat no-caps to="/users" label="Manage users & roles"/><p class="muted">Access applies to the server, its applications, metrics, and incidents. Platform administrators can create users and manage assignments in Users & roles.</p><template v-if="selected"><div v-for="m in members" :key="m.id" class="detail-line"><span>{{m.user__username}}</span><span class="member-role">{{m.role}}<q-btn v-if="m.user__username!==store.user?.username" flat round size="sm" aria-label="Revoke member access" @click="revokeMember(m.id)"><Trash2 :size="16"/></q-btn></span></div><form @submit.prevent="saveMember" class="form-fields"><q-input v-model="memberName" outlined label="Existing username" required/><q-select v-model="memberRole" :options="['viewer','operator','admin']" outlined label="Role"/><q-btn type="submit" outline no-caps label="Assign access"/></form></template><p v-else class="muted">Choose a server in Alert rules to manage its access.</p></div></section></div><section class="notice system-note"><Info :size="20"/><span>Raw metrics and probe history are retained for 14 days. Long-term rollups and advanced database, backup, cron, and security adapters are follow-up milestones. Current adapter coverage is documented in the project README.</span></section>
<q-dialog v-model="adding"><q-card class="form-dialog"><form @submit.prevent="saveMaintenance"><q-card-section><h2>Schedule maintenance</h2><p class="muted">Enter start and end in this device's local timezone.</p></q-card-section><q-card-section class="form-fields"><q-select v-model="mw.server" :options="manageable.map(s=>({label:s.name,value:s.id}))" emit-value map-options outlined label="Server"/><q-input v-model="mw.starts_at" outlined type="datetime-local" label="Start" stack-label required/><q-input v-model="mw.ends_at" outlined type="datetime-local" label="End" stack-label required/><q-input v-model="mw.reason" outlined label="Reason" maxlength="200" required/><div v-if="error" class="error-box">{{error}}</div></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn type="submit" no-caps unelevated color="primary" label="Schedule" :loading="busy"/></q-card-actions></form></q-card></q-dialog>
</template>
